css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 9px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 4px;}
.mz .rec-texto{font-size: 14px; line-height: 1.45;}
.mz .rec-texto b{font-size: 16px;}
.mz .rec-op{font-size: 17px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .calc-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 34px;}
.mz .resp-fila{display: flex; align-items: center; gap: 7px; font-size: 17px; font-weight: 700; font-family: sans-serif; flex-wrap: wrap;}
.mz .caja{width: 46px; height: 30px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block;}
.mz .pista{font-family: sans-serif; font-size: 11.5px; font-weight: 600; color: #555; margin: -4px 0 9px;}
.mz .tabla-dm{width: 100%; border-collapse: collapse; font-family: sans-serif;}
.mz .tabla-dm th,.mz .tabla-dm td{border: 1.6px solid var(--bosque); text-align: center; padding: 9px 4px; font-size: 17px; font-weight: 700;}
.mz .tabla-dm th{background: #eee; font-size: 14px;}
.mz .tabla-dm .dado{background: #f3f3f3;}
.mz .problema{border: 1.8px solid var(--bosque); border-radius: 10px; padding: 11px 14px; font-size: 14.5px; line-height: 1.4;}
.mz .problema .op-line{display: flex; align-items: center; gap: 10px; margin-top: 10px; font-size: 15px; font-weight: 700; font-family: sans-serif;}
.mz .problema .et{font-family: sans-serif; font-size: 12px; color: #555;}
.mz .problema .cajp{width: 70px; height: 30px; border: 1.6px dashed #000; border-radius: 6px; display: inline-block;}
.mz .problema .sol{border-bottom: 1.5px solid var(--bosque); flex: 1; min-height: 22px;}
.mz .problema,.mz .rec-texto{line-height: 1.725 !important;}
